--
-- Table structure for table `MovieBillingHead`
--

DROP TABLE IF EXISTS `MovieBillingHead`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `MovieBillingHead` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `clientId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `compulsionType` enum('FIXED_COMPULSORY','FIXED_OPTIONAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FIXED_COMPULSORY',
  `costType` enum('WHOLE_COST','PER_UNIT_COST') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WHOLE_COST',
  `domesticCost` decimal(12,2) NOT NULL DEFAULT '0.00',
  `intlCost` decimal(12,2) NOT NULL DEFAULT '0.00',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `domesticCompulsionType` enum('FIXED_COMPULSORY','FIXED_OPTIONAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FIXED_COMPULSORY',
  `intlCompulsionType` enum('FIXED_COMPULSORY','FIXED_OPTIONAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FIXED_COMPULSORY',
  `domesticActive` tinyint(1) NOT NULL DEFAULT '1',
  `intlActive` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `MovieBillingHead_clientId_name_key` (`clientId`,`name`),
  KEY `MovieBillingHead_clientId_isActive_idx` (`clientId`,`isActive`),
  KEY `MovieBillingHead_name_idx` (`name`),
  CONSTRAINT `MovieBillingHead_clientId_fkey` FOREIGN KEY (`clientId`) REFERENCES `Client` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

