--
-- Table structure for table `TimeEntry`
--

DROP TABLE IF EXISTS `TimeEntry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TimeEntry` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `projectId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subProjectId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employeeId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `countryId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `movieId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `languageId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `workDate` datetime(3) NOT NULL,
  `minutesSpent` int NOT NULL,
  `isBillable` tinyint(1) NOT NULL DEFAULT '1',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` enum('DRAFT','SUBMITTED','APPROVED','REJECTED','REVISED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `taskName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `assetTypeId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `TimeEntry_projectId_workDate_idx` (`projectId`,`workDate`),
  KEY `TimeEntry_employeeId_workDate_idx` (`employeeId`,`workDate`),
  KEY `TimeEntry_status_idx` (`status`),
  KEY `TimeEntry_subProjectId_idx` (`subProjectId`),
  KEY `TimeEntry_countryId_idx` (`countryId`),
  KEY `TimeEntry_movieId_idx` (`movieId`),
  KEY `TimeEntry_languageId_idx` (`languageId`),
  KEY `TimeEntry_assetTypeId_idx` (`assetTypeId`),
  CONSTRAINT `TimeEntry_assetTypeId_fkey` FOREIGN KEY (`assetTypeId`) REFERENCES `AssetType` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_countryId_fkey` FOREIGN KEY (`countryId`) REFERENCES `Country` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_employeeId_fkey` FOREIGN KEY (`employeeId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_languageId_fkey` FOREIGN KEY (`languageId`) REFERENCES `Language` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_movieId_fkey` FOREIGN KEY (`movieId`) REFERENCES `Movie` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_projectId_fkey` FOREIGN KEY (`projectId`) REFERENCES `Project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `TimeEntry_subProjectId_fkey` FOREIGN KEY (`subProjectId`) REFERENCES `SubProject` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

